import { outputCues, serializeSrt } from './subtitles';
import type { EditSettings } from './types';
export interface RecipeResources { captions: string; fonts: string }
export const resourcePaths = (prefix = 'frame'): RecipeResources => ({ captions: `${prefix}-captions.srt`, fonts: 'fonts' });
/** Paths are generated by the engine, never supplied by project documents. */
export const filterPath = (path: string) => `'${path.replace(/\\/g, '/').replace(/:/g, '\\:').replace(/'/g, "'\\''")}'`;
export function recipeFiles(edit: EditSettings, paths: RecipeResources): { path: string; text: string }[] {
  return edit.subtitles.mode !== 'none' && outputCues(edit).length ? [{ path: paths.captions, text: serializeSrt(outputCues(edit)) }] : [];
}
